use crate::{
    domain::{
        models::{
            entity_details::{
                DeclaredFunding, FunderFunding, FunderProfile, FunderReference, MemberDetails,
                MemberProfile, RecentDeclaration, RecipientAllocation,
            },
            funder::{Funder, FunderId, FunderKind},
            parliament_member::MemberId,
        },
        repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
    },
    outbound::postgres::ExposedDatabase,
};
use std::str::FromStr;

const CURRENCY_WHITESPACE: &str = "\t\n\u{000b}\u{000c}\r \u{0085}\u{00a0}\u{1680}\u{2000}\u{2001}\u{2002}\u{2003}\u{2004}\u{2005}\u{2006}\u{2007}\u{2008}\u{2009}\u{200a}\u{2028}\u{2029}\u{202f}\u{205f}\u{3000}\u{feff}";

impl EntityDetailsRepo for ExposedDatabase {
    async fn member(
        &self,
        id: MemberId,
        recent_limit: usize,
    ) -> Result<Option<MemberDetails>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let row = sqlx::query!(
            "SELECT parliament_member_id, name, party_id, party_name, latest_membership_from, is_current_commons,
                (SELECT count(*) FROM exposed.declarations d WHERE d.member_id = m.id) AS \"declaration_count!\"
             FROM exposed.members m WHERE parliament_member_id = $1", i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
        ).fetch_optional(&mut *tx).await?;
        let Some(row) = row else {
            return Ok(None);
        };
        let member = MemberProfile {
            id,
            name: row.name,
            party_id: row.party_id,
            party_name: row.party_name,
            membership_from: row.latest_membership_from,
            is_current_commons: row.is_current_commons,
        };
        let rows = sqlx::query!(
            "WITH recent AS (
                SELECT d.source_declaration_id, d.category_name, d.registration_date
                FROM exposed.declarations d JOIN exposed.members m ON m.id = d.member_id
                WHERE m.parliament_member_id = $1
                ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC LIMIT $2
             )
             SELECT d.source_declaration_id, d.category_name, d.registration_date,
                e.id AS \"entry_id?\", e.amount, e.currency, e.payment_type, f.id AS \"funder_id?\", f.funder_name AS \"funder_name?\"
             FROM recent d LEFT JOIN exposed.funding_entries e ON e.source_declaration_id = d.source_declaration_id
             LEFT JOIN exposed.funders f ON f.id = e.funder_id
             ORDER BY d.registration_date DESC NULLS LAST, d.source_declaration_id DESC, e.id",
             i32::try_from(id.value()).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?,
             i64::try_from(recent_limit).map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?
        ).fetch_all(&mut *tx).await?;
        let mut declarations: Vec<RecentDeclaration> = Vec::new();
        for row in rows {
            if declarations
                .last()
                .is_none_or(|declaration| declaration.source_id != row.source_declaration_id)
            {
                declarations.push(RecentDeclaration {
                    source_id: row.source_declaration_id,
                    category_name: row.category_name,
                    registered_at: row
                        .registration_date
                        .map(|date| {
                            chrono::DateTime::from_timestamp(
                                date.unix_timestamp(),
                                date.nanosecond(),
                            )
                            .ok_or_else(|| {
                                EntityDetailsRepoError::DatabaseError(
                                    "Stored registration date is out of range".into(),
                                )
                            })
                        })
                        .transpose()?,
                    entries: Vec::new(),
                });
            }
            if row.entry_id.is_some() {
                let funder = row
                    .funder_id
                    .zip(row.funder_name)
                    .map(|(id, name)| FunderReference {
                        id: FunderId::new(id),
                        name,
                    });
                if let Some(declaration) = declarations.last_mut() {
                    declaration.entries.push(DeclaredFunding {
                        funder,
                        amount: row.amount,
                        currency: row.currency,
                        payment_type: row.payment_type,
                    });
                }
            }
        }
        tx.commit().await?;
        Ok(Some(MemberDetails {
            member,
            declarations,
            declaration_count: row.declaration_count,
            declaration_limit: recent_limit,
        }))
    }

    async fn funder_funding(
        &self,
        id: FunderId,
    ) -> Result<Option<FunderFunding>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let row = sqlx::query!(
            "SELECT funder_name, funder_kind, company_number FROM exposed.funders WHERE id = $1",
            id.value()
        )
        .fetch_optional(&mut *tx)
        .await?;
        let Some(row) = row else {
            return Ok(None);
        };
        let kind = row
            .funder_kind
            .as_deref()
            .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
            .map_err(|error| EntityDetailsRepoError::DatabaseError(error.to_string()))?;
        let profile = FunderProfile {
            funder: Funder::new(id, row.funder_name, kind),
            company_number: row.company_number,
        };
        let rows = sqlx::query!(
            "WITH funding AS (
                SELECT source_declaration_id, amount, NULLIF(btrim(currency, $2), '') AS currency
                FROM exposed.funding_entries WHERE funder_id = $1
             )
             SELECT m.parliament_member_id, m.name, m.party_id, m.party_name, m.latest_membership_from, m.is_current_commons,
                e.currency,
                CASE WHEN e.currency IS NOT NULL THEN sum(e.amount) END AS known_total,
                count(*) AS \"entry_count!\", count(*) FILTER (WHERE e.amount IS NULL) AS \"unknown_amount_count!\"
             FROM funding e JOIN exposed.declarations d ON d.source_declaration_id = e.source_declaration_id
             JOIN exposed.members m ON m.id = d.member_id
             GROUP BY m.id, e.currency
             ORDER BY m.parliament_member_id, currency NULLS LAST", id.value(), CURRENCY_WHITESPACE
        ).fetch_all(&mut *tx).await?;
        let allocations = rows
            .into_iter()
            .map(|row| {
                let id = row
                    .parliament_member_id
                    .to_string()
                    .parse::<MemberId>()
                    .map_err(EntityDetailsRepoError::DatabaseError)?;
                Ok(RecipientAllocation {
                    member: MemberProfile {
                        id,
                        name: row.name,
                        party_id: row.party_id,
                        party_name: row.party_name,
                        membership_from: row.latest_membership_from,
                        is_current_commons: row.is_current_commons,
                    },
                    currency: row.currency,
                    known_total: row.known_total,
                    entry_count: row.entry_count,
                    unknown_amount_count: row.unknown_amount_count,
                })
            })
            .collect::<Result<Vec<_>, EntityDetailsRepoError>>()?;
        tx.commit().await?;
        Ok(Some(FunderFunding {
            profile,
            allocations,
        }))
    }
}

#[cfg(test)]
mod tests;

impl From<sqlx::Error> for EntityDetailsRepoError {
    fn from(error: sqlx::Error) -> Self {
        Self::DatabaseError(error.to_string())
    }
}
//! Entity profiles and summaries from a shared exact aggregate.

mod interface;
pub use interface::EntityDetailsService;

use crate::domain::{
    models::{
        entity_details::{
            CurrencyBreakdown, FunderDetails, FunderFunding, MemberDetails, PartyTotal,
            RecipientAllocation,
        },
        funder::FunderId,
        parliament_member::MemberId,
    },
    repositories::entity_details::{EntityDetailsRepo, EntityDetailsRepoError},
};
use std::{cmp::Ordering, collections::BTreeMap};
use thiserror::Error;

const RECENT_DECLARATIONS: usize = 20;
const TOP_RECIPIENTS: usize = 10;

/// Entity detail lookup failure.
#[derive(Debug, Error)]
pub enum EntityDetailsError {
    /// No stored identity matches the request.
    #[error("entity not found")]
    NotFound,
    /// Private database diagnostics.
    #[error(transparent)]
    Unexpected(#[from] EntityDetailsRepoError),
}

/// Detail service owns summary rules and presentation limits.
#[derive(Clone)]
pub struct Service<R> {
    repo: R,
}

impl<R> Service<R> {
    /// Creates a detail service.
    #[must_use]
    pub const fn new(repo: R) -> Self {
        Self { repo }
    }
}

impl<R: EntityDetailsRepo> EntityDetailsService for Service<R> {
    async fn member(&self, id: MemberId) -> Result<MemberDetails, EntityDetailsError> {
        self.repo
            .member(id, RECENT_DECLARATIONS)
            .await?
            .ok_or(EntityDetailsError::NotFound)
    }
    async fn funder(&self, id: FunderId) -> Result<FunderDetails, EntityDetailsError> {
        self.repo
            .funder_funding(id)
            .await?
            .map(summarize_funder)
            .ok_or(EntityDetailsError::NotFound)
    }
}

fn compare_allocations(left: &RecipientAllocation, right: &RecipientAllocation) -> Ordering {
    right
        .known_total
        .cmp(&left.known_total)
        .then_with(|| left.member.id.value().cmp(&right.member.id.value()))
        .then_with(|| left.member.name.cmp(&right.member.name))
}

fn summarize_funder(funding: FunderFunding) -> FunderDetails {
    let mut entry_count = 0;
    let mut unknown_currency_count = 0;
    let mut currencies: BTreeMap<String, Vec<RecipientAllocation>> = BTreeMap::new();
    for allocation in funding.allocations {
        entry_count += allocation.entry_count;
        if let Some(currency) = &allocation.currency {
            currencies
                .entry(currency.clone())
                .or_default()
                .push(allocation);
        } else {
            unknown_currency_count += allocation.entry_count;
        }
    }
    let currencies = currencies
        .into_iter()
        .map(|(currency, mut allocations)| {
            let mut parties: BTreeMap<(i32, String), PartyTotal> = BTreeMap::new();
            for allocation in &allocations {
                let party = parties
                    .entry((
                        allocation.member.party_id,
                        allocation.member.party_name.clone(),
                    ))
                    .or_insert_with(|| PartyTotal {
                        party_id: allocation.member.party_id,
                        party_name: allocation.member.party_name.clone(),
                        amount: None,
                        entry_count: 0,
                        unknown_amount_count: 0,
                    });
                if let Some(amount) = &allocation.known_total {
                    if let Some(total) = &mut party.amount {
                        *total += amount;
                    } else {
                        party.amount = Some(amount.clone());
                    }
                }
                party.entry_count += allocation.entry_count;
                party.unknown_amount_count += allocation.unknown_amount_count;
            }
            let mut parties: Vec<_> = parties.into_values().collect();
            parties.sort_by(|left, right| {
                right
                    .amount
                    .cmp(&left.amount)
                    .then_with(|| left.party_name.cmp(&right.party_name))
                    .then_with(|| left.party_id.cmp(&right.party_id))
            });
            allocations.sort_by(compare_allocations);
            allocations.truncate(TOP_RECIPIENTS);
            CurrencyBreakdown {
                currency,
                parties,
                top_recipients: allocations,
            }
        })
        .collect();
    FunderDetails {
        profile: funding.profile,
        currencies,
        entry_count,
        unknown_currency_count,
        recipient_limit: TOP_RECIPIENTS,
    }
}
export type DetailRoute =
  | { kind: "search" }
  | { kind: "member"; id: string }
  | { kind: "funder"; id: string }
  | { kind: "invalid" };

const funderIdPattern =
  /^[\da-f]{8}-[\da-f]{4}-[\da-f]{4}-[\da-f]{4}-[\da-f]{12}$/iu;
const memberIdPattern = /^[1-9]\d*$/u;

export function readDetailRoute(path: string): DetailRoute {
  if (path === "/") return { kind: "search" };
  const member = /^\/members\/([^/]+)\/?$/u.exec(path);
  if (
    member &&
    memberIdPattern.test(member[1]) &&
    Number(member[1]) <= 2147483647
  )
    return { kind: "member", id: member[1] };
  const funder = /^\/funders\/([^/]+)\/?$/u.exec(path);
  if (funder && funderIdPattern.test(funder[1]))
    return { kind: "funder", id: funder[1] };
  return { kind: "invalid" };
}

export interface MemberProfile {
  id: string;
  name: string;
  partyName: string;
  membershipFrom: string;
  isCurrentCommons: boolean;
}

export interface FundingEntry {
  funder: { id: string; name: string } | null;
  amount: string | null;
  currency: string | null;
  paymentType: string | null;
}

export interface MemberDetails {
  member: MemberProfile;
  declarations: {
    sourceId: number;
    categoryName: string;
    registeredAt: string | null;
    entries: FundingEntry[];
  }[];
  declarationCount: number;
  declarationLimit: number;
}

interface Total {
  amount: string | null;
  entryCount: number;
  unknownAmountCount: number;
}

export interface FunderDetails {
  funder: {
    id: string;
    name: string;
    funderKind: string | null;
    companyNumber: string | null;
  };
  currencies: {
    currency: string;
    parties: (Total & { partyName: string })[];
    topRecipients: (Total & { member: MemberProfile })[];
  }[];
  entryCount: number;
  unknownCurrencyCount: number;
  recipientLimit: number;
}

export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

function malformed(): never {
  throw new Error("Details returned an unexpected response. Try again.");
}
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function record(value: unknown): Record<string, unknown> {
  return isRecord(value) ? value : malformed();
}
function text(value: unknown): string {
  return typeof value === "string" ? value : malformed();
}
function nullableText(value: unknown): string | null {
  return value === null ? null : text(value);
}
function count(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0
    ? value
    : malformed();
}
function list(value: unknown): unknown[] {
  return Array.isArray(value) ? value : malformed();
}
function decimal(value: unknown): string | null {
  const result = nullableText(value);
  if (result !== null && !/^-?\d+(?:\.\d+)?$/u.test(result)) return malformed();
  return result;
}
function identity(value: unknown, kind: "MP" | "Funder"): string {
  const id = text(value);
  if (
    kind === "MP"
      ? !memberIdPattern.test(id) || Number(id) > 2147483647
      : !funderIdPattern.test(id)
  )
    return malformed();
  return id;
}
function memberProfile(value: unknown): MemberProfile {
  const row = record(value);
  if (typeof row.is_current_commons !== "boolean") return malformed();
  return {
    id: identity(row.id, "MP"),
    name: text(row.name),
    partyName: text(row.party_name),
    membershipFrom: text(row.membership_from),
    isCurrentCommons: row.is_current_commons,
  };
}
function readMember(value: unknown): MemberDetails {
  const row = record(value);
  return {
    member: memberProfile(row.member),
    declarationCount: count(row.declaration_count),
    declarationLimit: count(row.declaration_limit),
    declarations: list(row.declarations).map((value) => {
      const declaration = record(value);
      const registeredAt = nullableText(declaration.registered_at);
      if (registeredAt !== null && !Number.isFinite(Date.parse(registeredAt)))
        return malformed();
      return {
        sourceId: count(declaration.source_id),
        categoryName: text(declaration.category_name),
        registeredAt,
        entries: list(declaration.entries).map((value) => {
          const entry = record(value);
          const funder = entry.funder === null ? null : record(entry.funder);
          return {
            funder:
              funder === null
                ? null
                : {
                    id: identity(funder.id, "Funder"),
                    name: text(funder.name),
                  },
            amount: decimal(entry.amount),
            currency: nullableText(entry.currency),
            paymentType: nullableText(entry.payment_type),
          };
        }),
      };
    }),
  };
}
function total(row: Record<string, unknown>): Total {
  return {
    amount: decimal(row.amount),
    entryCount: count(row.entry_count),
    unknownAmountCount: count(row.unknown_amount_count),
  };
}
function readFunder(value: unknown): FunderDetails {
  const row = record(value);
  const funder = record(row.funder);
  return {
    funder: {
      id: identity(funder.id, "Funder"),
      name: text(funder.name),
      funderKind: nullableText(funder.funder_kind),
      companyNumber: nullableText(funder.company_number),
    },
    entryCount: count(row.entry_count),
    unknownCurrencyCount: count(row.unknown_currency_count),
    recipientLimit: count(row.recipient_limit),
    currencies: list(row.currencies).map((value) => {
      const group = record(value);
      const currency = text(group.currency);
      if (!currency.trim()) return malformed();
      return {
        currency,
        parties: list(group.parties).map((value) => {
          const party = record(value);
          return { ...total(party), partyName: text(party.party_name) };
        }),
        topRecipients: list(group.top_recipients).map((value) => {
          const recipient = record(value);
          return {
            ...total(recipient),
            member: memberProfile(recipient.member),
          };
        }),
      };
    }),
  };
}

export async function loadDetails(
  route: Extract<DetailRoute, { kind: "member" | "funder" }>,
  signal: AbortSignal,
): Promise<DetailState> {
  const controller = new AbortController();
  const cancel = () => controller.abort();
  signal.addEventListener("abort", cancel, { once: true });
  if (signal.aborted) cancel();
  let timedOut = false;
  const timer = setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, 10_000);
  try {
    const response = await fetch(
      `/api/${route.kind === "member" ? "members" : "funders"}/${route.id}`,
      { signal: controller.signal },
    );
    if (response.status === 404) return { kind: "not-found" };
    if (!response.ok)
      throw new Error(
        "The details service is unavailable. Try again in a moment.",
      );
    const body: unknown = await response.json();
    const state: DetailState =
      route.kind === "member"
        ? { kind: "member", details: readMember(body) }
        : { kind: "funder", details: readFunder(body) };
    if (
      (state.kind === "member"
        ? state.details.member.id
        : state.details.funder.id
      ).toLowerCase() !== route.id.toLowerCase()
    )
      return malformed();
    return state;
  } catch (error) {
    if (signal.aborted) throw error;
    return {
      kind: "error",
      message: timedOut
        ? "Details are taking too long. Try again."
        : error instanceof Error &&
            !(error instanceof TypeError || error instanceof SyntaxError)
          ? error.message
          : "Couldn’t connect to details. Check your connection and try again.",
    };
  } finally {
    clearTimeout(timer);
    signal.removeEventListener("abort", cancel);
  }
}

export function backToSearch(): string {
  const params = new URLSearchParams(window.location.search);
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
}

export function registrationDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

